# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM\'DA AKRABALIK (SILA-İ RAHİM) VE KOMŞULUK HUKUKU</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Sıla-i Rahim (Akrabalık Bağını Gözetme)</text>\n  <text x="40" y="98" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Tanım:</tspan> Akrabaları ziyaret etme, iletişim</text>\n  <text x="48" y="115" font-size="11" fill="#1e3a8a">kurma, sevinç ve üzüntülerini paylaşma</text>\n  <text x="40" y="138" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Kur\'ânî İlke:</tspan> "Allah adaleti, ihsanı ve</text>\n  <text x="48" y="155" font-size="11" fill="#1e3a8a">yakınlara vermeyi emreder." (Nahl, 16/90)</text>\n  <text x="40" y="178" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">İnfakta Öncelik:</tspan> Muhtaç akrabaya yapılan</text>\n  <text x="48" y="195" font-size="11" fill="#1e3a8a">yardım hem sadaka hem sıla-i rahimdir.</text>\n  <text x="40" y="218" font-size="11" font-weight="bold" fill="#1d4ed8">• Zıddı: Kat\'-ı rahim (bağları koparmak)</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Komşuluk Hakları ve Sorumluluklar</text>\n  <text x="375" y="98" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Kur\'ânî İlke:</tspan> Yakın ve uzak komşuya</text>\n  <text x="383" y="115" font-size="11" fill="#14532d">iyilik yapmak (Nisâ suresi, 4/36)</text>\n  <text x="375" y="138" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Güven İlkesi:</tspan> Elinden ve dilinden komşusunun</text>\n  <text x="383" y="155" font-size="11" fill="#14532d">emniyette olduğu mümin (Hadis-i Şerif)</text>\n  <text x="375" y="178" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Paylaşma:</tspan> "Komşusu açken tok yatan</text>\n  <text x="383" y="195" font-size="11" fill="#14532d">bizden değildir." (Sosyal duyarlılık)</text>\n  <text x="375" y="218" font-size="11" font-weight="bold" fill="#15803d">• İnanç farkı gözetmeksizin komşu hakkı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KOMŞULUK HAKLARININ KAPSAMI VE SINIFLANDIRILMASI</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="127" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Komşu Türleri ve Hakları</text>\n  <text x="38" y="102" font-size="10.5" font-weight="bold" fill="#b45309">1. Üç Hak Sahibi Komşu:</text>\n  <text x="46" y="118" font-size="10" fill="#78350f">Akraba ve Müslüman olan komşu</text>\n  <text x="46" y="132" font-size="10" fill="#78350f">(Komşuluk + Akrabalık + İslam hakkı)</text>\n  <text x="38" y="155" font-size="10.5" font-weight="bold" fill="#b45309">2. İki Hak Sahibi Komşu:</text>\n  <text x="46" y="171" font-size="10" fill="#78350f">Müslüman komşu (Komşu + İslam)</text>\n  <text x="38" y="194" font-size="10.5" font-weight="bold" fill="#b45309">3. Bir Hak Sahibi Komşu:</text>\n  <text x="46" y="210" font-size="10" fill="#78350f">Gayrimüslim komşu (Komşuluk hakkı)</text>\n\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.8"/>\n  <text x="350" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Olumlu Sorumluluklar</text>\n  <text x="260" y="102" font-size="10.5" fill="#334155">• Selamlaşmak ve hal hatır sormak</text>\n  <text x="260" y="124" font-size="10.5" fill="#334155">• Hastalıkta ziyaret, taziye ve</text>\n  <text x="268" y="140" font-size="10.5" fill="#475569">sevinçli günlerde tebrik</text>\n  <text x="260" y="162" font-size="10.5" fill="#334155">• Pişen yemekten ikram etmek ve</text>\n  <text x="268" y="178" font-size="10.5" fill="#475569">ihtiyaç anında ödünç vermek</text>\n  <text x="260" y="200" font-size="10.5" font-weight="bold" fill="#1e40af">• Malını, ırzını ve evini korumak</text>\n\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="572" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Kaçınılması Gerekenler</text>\n  <text x="483" y="102" font-size="10.5" fill="#334155">• Gürültü, duman veya çöple</text>\n  <text x="491" y="118" font-size="10.5" fill="#475569">komşuya eziyet vermek</text>\n  <text x="483" y="140" font-size="10.5" fill="#334155">• Evinin mahremiyetini (pencere/</text>\n  <text x="491" y="156" font-size="10.5" fill="#475569">balkon) gözetlemek</text>\n  <text x="483" y="178" font-size="10.5" fill="#334155">• Ortak yaşam alanlarını (merdiven,</text>\n  <text x="491" y="194" font-size="10.5" fill="#475569">bahçe, otopark) işgal etmek</text>\n  <text x="483" y="216" font-size="10.5" font-weight="bold" fill="#991b1b">• Kusurlarını araştırıp yaymak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TOPLUMSAL BARIŞI İNŞA EDEN VE ZEDELEYEN TUTUMLAR (HUCURÂT 10-12)</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Barışı Koruyan Faziletler</text>\n  <text x="40" y="98" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Uhuvvet ve Islah:</tspan> Kardeşlik ve arayı bulma</text>\n  <text x="40" y="122" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Hüsnüzan:</tspan> İnsanlar hakkında iyi düşünme</text>\n  <text x="40" y="146" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Îsâr (Diğergamlık):</tspan> Kendi ihtiyacı varken</text>\n  <text x="48" y="163" font-size="11" fill="#14532d">kardeşini öz nefsine tercih etme</text>\n  <text x="40" y="186" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Setr-i Uyûb:</tspan> Başkasının kusurunu örtme</text>\n  <text x="40" y="210" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Adalet, Emanet ve Mahremiyete Saygı</tspan></text>\n\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Kardeşliği Yıkan Davranışlar</text>\n  <text x="375" y="98" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Suizan:</tspan> Delilsiz kötü zan ve önyargı</text>\n  <text x="375" y="122" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Tecessüs:</tspan> Gizli halleri ve mahremi araştırma</text>\n  <text x="375" y="146" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Gıybet:</tspan> Arkadan hoşlanılmayacak konuşma</text>\n  <text x="375" y="170" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">İftira (Bühtan):</tspan> Olmayan suçu isnat etme</text>\n  <text x="375" y="194" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Nemîme:</tspan> Söz taşıyarak ara bozma (koğuculuk)</text>\n  <text x="375" y="218" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Haset ve Kibir:</tspan> Kıskançlık ve büyüklenme</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
